create table if not exists public.ils_professional_assignment_mutation_failure_telemetry (id uuid primary key default gen_random_uuid(), assignment_link_id uuid, work_item_id uuid, work_stream text, professional_user_id uuid, operation text, requested_status text, failure_code text not null, failure_class text not null, safe_message text not null, source_gate text not null, occurred_at timestamptz not null default now()); alter table public.ils_professional_assignment_mutation_failure_telemetry enable row level security; alter table public.ils_professional_assignment_mutation_failure_telemetry force row level security; revoke all on public.ils_professional_assignment_mutation_failure_telemetry from anon,authenticated; create index if not exists ils_assignment_mutation_failure_code_idx on public.ils_professional_assignment_mutation_failure_telemetry(failure_code,occurred_at); create index if not exists ils_assignment_mutation_failure_link_idx on public.ils_professional_assignment_mutation_failure_telemetry(assignment_link_id,occurred_at); create table if not exists public.ils_professional_assignment_mutation_observability_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_mutation_observability_tests enable row level security; alter table public.ils_professional_assignment_mutation_observability_tests force row level security; revoke all on public.ils_professional_assignment_mutation_observability_tests from anon,authenticated; insert into public.ils_professional_assignment_mutation_observability_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('AUTH_REQUIRED','TELEMETRY_CODED','TELEMETRY_CODED',true,'Unauthenticated mutation failures map to a structured security failure code.'),('ASSIGNMENT_NOT_FOUND','TELEMETRY_CODED','TELEMETRY_CODED',true,'Missing or foreign assignment is observable without exposing sensitive details.'),('INVALID_OPERATION','TELEMETRY_CODED','TELEMETRY_CODED',true,'Unsupported operations have a deterministic failure class.'),('STATUS_MISMATCH','TELEMETRY_CODED','TELEMETRY_CODED',true,'Operation/target mismatch is observable.'),('INVALID_TRANSITION','TELEMETRY_CODED','TELEMETRY_CODED',true,'Lifecycle rejection is observable.'),('STALE_ELIGIBILITY','TELEMETRY_CODED','TELEMETRY_CODED',true,'Activation eligibility failure is observable.'),('REPLAY_BLOCK','TELEMETRY_CODED','TELEMETRY_CODED',true,'Replay/terminal-state rejection is observable.'),('CROSS_STREAM','TELEMETRY_CODED','TELEMETRY_CODED',true,'Cross-stream misuse is classified without broadening access.'),('SAFE_MESSAGE','NO_SECRETS','NO_SECRETS',true,'Telemetry safe_message is designed for operational diagnostics without credentials or gateway secrets.'),('DIRECT_CLIENT_ACCESS','BLOCK','BLOCK',true,'Telemetry is backend-only with RLS and FORCE RLS.'),('EMPTY_LIVE_STATE','PASS','PASS',true,'No synthetic live failures are inserted into the telemetry table.');